import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  mix,
  smoothstep,
  texture,
  fract,
  sin,
  dot,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem =
    items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Pricing 3' };

  const group = new Group();
  group.name = 'hub-pricing-card-2-label';

  // ---- engineered gradient + grain surface (card label backdrop) ----
  const W = 1.6;
  const H = 1.0;
  const geo = new PlaneGeometry(W, H, 1, 1);

  const inkC = new THREE.Color(colors.ink);
  const surfaceC = new THREE.Color(colors.surface);
  const accentC = new THREE.Color(colors.accent);

  const uvNode = uv();

  const gradientNode = mix(
    vec3(surfaceC.r, surfaceC.g, surfaceC.b),
    vec3(inkC.r, inkC.g, inkC.b),
    uvNode.y
  );

  // subtle procedural grain
  const grainSeed = dot(uvNode.mul(1024.0), vec2(12.9898, 78.233));
  const grain = fract(sin(grainSeed).mul(43758.5453));
  const grainSigned = grain.sub(0.5).mul(0.035);

  // thin accent underline near bottom edge of the card label
  const underline = smoothstep(0.0, 0.02, uvNode.y).oneMinus().mul(
    smoothstep(0.0, 0.04, uvNode.y)
  );
  const accentNode = vec3(accentC.r, accentC.g, accentC.b);

  function buildColorNode(texNode) {
    let base = gradientNode.add(grainSigned);
    base = mix(base, accentNode, underline.mul(0.65));
    if (texNode) {
      base = mix(base, texNode.rgb, texNode.a.mul(0.9));
    }
    return base;
  }

  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
  });
  material.colorNode = buildColorNode(null);
  material.opacityNode = null;

  const plane = new Mesh(geo, material);
  plane.name = 'card-label-surface';
  group.add(plane);

  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        const texNode = texture(tex, uvNode);
        material.colorNode = buildColorNode(texNode);
        material.needsUpdate = true;
      })
      .catch(() => {
        // fail silent — gradient-only surface remains valid
      });
  }

  // ---- headline text: "Pricing 3" ----
  const fontSize = headlineItem.typography?.fontSize ?? 39;
  const textObj = ctx.fontAtlas.createText(headlineItem.text ?? 'Pricing 3', {
    fontSize,
    color: colors.paper,
    align: 'center',
  });
  textObj.position.set(0, 0, 0.01);
  group.add(textObj);

  // apply any cinematic primitives (none configured for this node, but honor contract)
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(group, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- weighted-settle entrance (static composition, single mount motion only) ----
  group.scale.setScalar(0.98);
  material.opacity = 0;
  const tl = gsap.timeline();
  tl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }).to(
    material,
    {
      opacity: 1,
      duration: 0.6,
      ease: 'power2.out',
    },
    0
  );

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    for (const h of primitiveHandles) {
      try {
        h.cleanup?.();
      } catch (e) {
        // no-op
      }
    }
    geo.dispose();
    material.dispose();
    if (loadedTexture?.dispose) loadedTexture.dispose();
    if (textObj?.userData?.cleanup) textObj.userData.cleanup();
  };

  return group;
}
